-- 2, 2147483648
-- 2, 2147483649
SELECT COUNT(A.LINK_TO_EVENT) AS EVENT_COUNT, M.MAJOR_NAME FROM MEMBER MB JOIN ATTENDANCE A ON MB.MEMBER_ID = A.LINK_TO_MEMBER JOIN MAJOR M ON MB.LINK_TO_MAJOR = M.MAJOR_ID WHERE MB.FIRST_NAME = 'LUISA' AND MB.LAST_NAME = 'GUIDI' GROUP BY M.MAJOR_NAME;
-- ----------sql2------------
-- 4, 2147483648
SELECT COUNT(T3.LINK_TO_EVENT), T1.MAJOR_NAME FROM MAJOR AS T1 INNER JOIN MEMBER AS T2 ON T1.MAJOR_ID = T2.LINK_TO_MAJOR INNER JOIN ATTENDANCE AS T3 ON T2.MEMBER_ID = T3.LINK_TO_MEMBER WHERE T2.FIRST_NAME = 'LUISA' AND T2.LAST_NAME = 'GUIDI';

