SELECT CUSTOMERID, MAX(CONSUMPTION) AS MAXCONSUMPTION FROM YEARMONTH WHERE CUSTOMERID IN (SELECT CUSTOMERID FROM CUSTOMERS WHERE SEGMENT = 'KAM') GROUP BY CUSTOMERID ORDER BY MAXCONSUMPTION DESC LIMIT 1;
-- ----------sql2------------
-- 30, 29394
SELECT T2.CUSTOMERID, SUM(T2.CONSUMPTION) FROM CUSTOMERS AS T1 INNER JOIN YEARMONTH AS T2 ON T1.CUSTOMERID = T2.CUSTOMERID WHERE T1.SEGMENT = 'KAM' GROUP BY T2.CUSTOMERID ORDER BY SUM(T2.CONSUMPTION) DESC LIMIT 1;

